// pubspec.yaml: image_picker: ^1.1.0
import 'package:image_picker/image_picker.dart';

final picker = ImagePicker();

// ────── Pick a single image (gallery, compressed) ──────
Future<XFile?> pickOne() async {
  try {
    return await picker.pickImage(
      source: ImageSource.gallery,
      maxWidth: 1600,
      imageQuality: 85,     // JPEG 0-100
      requestFullMetadata: false, // skip GPS EXIF for privacy
    );
  } on PlatformException catch (e) {
    // 'photo_access_denied' on iOS, 'camera_access_denied' on Android
    return null;
  }
}

// ────── Multi-select (returns [] if user cancels) ──────
Future<List<XFile>> pickMany() async {
  final files = await picker.pickMultiImage(maxWidth: 1600, imageQuality: 85);
  return files;
}

// ────── Camera capture ──────
Future<XFile?> snap() async {
  return await picker.pickImage(source: ImageSource.camera, imageQuality: 90);
}

// ────── Video ──────
Future<XFile?> pickVideo() async {
  return await picker.pickVideo(source: ImageSource.gallery,
    maxDuration: const Duration(seconds: 60));
}

// ────── Android: recover from low-memory kill ──────
Future<void> _recoverLostData() async {
  if (!Platform.isAndroid) return;
  final lost = await picker.retrieveLostData();
  if (lost.file != null) { /* re-use lost.file */ }
  else if (lost.exception != null) { /* handle */ }
}

// ────── Upload flow using Dio ──────
Future<void> uploadAvatar(XFile file) async {
  final form = FormData.fromMap({
    'file': await MultipartFile.fromFile(file.path, filename: file.name),
  });
  await dio.post('/avatar', data: form,
    onSendProgress: (sent, total) => print('${sent / total * 100} %'));
}
